CREATE FUNCTION public.save_imported_source(p_id uuid,p_content text,p_modified text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.campaign_records SET content=p_content,source_modified_at=p_modified,version=version+1,updated_at=now(),sync_state='pending' WHERE id=p_id AND source_file_id IS NOT NULL AND version=1; IF NOT FOUND THEN RAISE EXCEPTION 'Fonte editada no site; preserve ambas as versões para revisão'; END IF; END $$; REVOKE ALL ON FUNCTION public.save_imported_source(uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.save_imported_source(uuid,text,text) TO service_role;